package tickerwire
import("context";"os";"testing";"time";"github.com/nats-io/nats.go";"nse-mtbt-handler/internal/feed")
func TestRealSubjectRoutingAndRetry(t *testing.T){url:=os.Getenv("MTBT_TEST_NATS_URL");if url==""{t.Skip("set MTBT_TEST_NATS_URL")};ctx,cancel:=context.WithTimeout(context.Background(),10*time.Second);defer cancel();nc,e:=nats.Connect(url,nats.NoReconnect());if e!=nil{t.Fatal(e)};defer nc.Close();js,e:=nc.JetStream();if e!=nil{t.Fatal(e)};m:=wireManifest();bus,e:=Open(ctx,nc,js,m);if e!=nil{t.Fatal(e)};defer js.DeleteStream(bus.Stream());sub,e:=bus.Subscribe(ctx,100);if e!=nil{t.Fatal(e)};defer sub.Unsubscribe();sub2,e:=bus.Subscribe(ctx,101);if e!=nil{t.Fatal(e)};defer sub2.Unsubscribe()
 c,e:=New(m,100,1,1,time.Now().UTC(),wireRaw(t,m),"");if e!=nil{t.Fatal(e)};for i:=0;i<2;i++{if e=bus.Publish(ctx,c);e!=nil{t.Fatal(e)}};msgs,e:=sub.Fetch(1,nats.MaxWait(time.Second));if e!=nil{t.Fatal(e)};decoded,e:=bus.Validate(msgs[0]);if e!=nil||decoded.Digest!=c.Digest{t.Fatal(e)};if e=msgs[0].AckSync();e!=nil{t.Fatal(e)};if _,e=sub2.Fetch(1,nats.MaxWait(30*time.Millisecond));e!=nats.ErrTimeout{t.Fatal("other ticker got packet",e)};info,e:=js.StreamInfo(bus.Stream());if e!=nil||info.State.Msgs!=1{t.Fatal(info,e)}
 hb,_:=feed.Encode(feed.Packet{Stream:m.StreamID,Type:feed.Heartbeat,LastSequence:1});control,e:=New(m,101,1,2,time.Now().UTC(),hb,"");if e!=nil{t.Fatal(e)};if e=bus.Publish(ctx,control);e!=nil{t.Fatal(e)};msgs,e=sub2.Fetch(1,nats.MaxWait(time.Second));if e!=nil{t.Fatal(e)};if _,e=bus.Validate(msgs[0]);e!=nil{t.Fatal(e)};msgs[0].AckSync()
 cfg:=info.Config;cfg.Description="wrong";if _,e=js.UpdateStream(&cfg);e!=nil{t.Fatal(e)};if _,e=Open(ctx,nc,js,m);e==nil{t.Fatal("mismatched manifest accepted")}
}
func TestStreamAndConsumerGuards(t *testing.T){cfg:=nats.StreamConfig{Name:"MATCH_83",Description:"known",Subjects:[]string{"mtbtmatch.83.*"},Storage:nats.FileStorage,Retention:nats.LimitsPolicy,Discard:nats.DiscardNew,MaxAge:24*time.Hour,MaxBytes:64<<20,MaxMsgSize:16384,Replicas:1,Duplicates:10*time.Minute};if e:=validateStreamConfig(&cfg,&cfg);e!=nil{t.Fatal(e)};for _,mutate:=range []func(*nats.StreamConfig){func(c *nats.StreamConfig){c.Subjects=nil},func(c *nats.StreamConfig){c.Description="other"},func(c *nats.StreamConfig){c.NoAck=true},func(c *nats.StreamConfig){c.Subjects=[]string{"wrong"}},func(c *nats.StreamConfig){c.Retention=nats.WorkQueuePolicy}}{other:=cfg;mutate(&other);if validateStreamConfig(&other,&cfg)==nil{t.Fatal("bad stream accepted")}}
 cc:=nats.ConsumerConfig{Durable:"ticker-100",FilterSubject:"mtbtmatch.83.100",AckPolicy:nats.AckExplicitPolicy,AckWait:30*time.Second,MaxAckPending:1,DeliverPolicy:nats.DeliverAllPolicy,ReplayPolicy:nats.ReplayInstantPolicy};other:=cc;other.DeliverPolicy=nats.DeliverNewPolicy;if validateConsumerConfig(&other,&cc)==nil{t.Fatal("skip consumer accepted")}
}
